import '../utils/cloud_dates.dart';

/// A QR pass an owner issued for a visitor (see supabase/visitor_passes.sql in
/// the ERP repo). The [code] is generated by the server.
class VisitorPass {
  final String code;
  final String visitorName;
  final String note;
  final DateTime validFrom;
  final DateTime validUntil;
  final int maxUses;
  final int uses;
  final String status; // active | used | revoked

  const VisitorPass({
    required this.code,
    required this.visitorName,
    required this.note,
    required this.validFrom,
    required this.validUntil,
    required this.maxUses,
    required this.uses,
    required this.status,
  });

  factory VisitorPass.fromMap(Map<String, dynamic> d) => VisitorPass(
        code: (d['Code'] ?? '').toString(),
        visitorName: (d['VisitorName'] ?? '').toString(),
        note: (d['Note'] ?? '').toString(),
        validFrom: parseFlexDate(d['ValidFrom']).toLocal(),
        validUntil: parseFlexDate(d['ValidUntil']).toLocal(),
        maxUses: (d['MaxUses'] as num?)?.toInt() ?? 1,
        uses: (d['Uses'] as num?)?.toInt() ?? 0,
        status: (d['Status'] ?? 'active').toString(),
      );

  bool get isExpired => DateTime.now().isAfter(validUntil);

  /// Whether the QR can still open the gate right now.
  bool get isUsable =>
      status == 'active' && !isExpired && uses < maxUses;

  /// What the QR encodes; the prefix lets a scanner tell it from other codes.
  String get qrData => 'GNT-V:$code';
}
